theorem resolvedInternalEdgeComplete_count {γ : ResolvedFeynmanSubgraph G}
    (hEC : ResolvedInternalEdgeComplete γ) {e : ResolvedFeynmanEdge}
    (hs : e.source ∈ γ.vertices) (ht : e.target ∈ γ.vertices) :
